  expect(turnItemHasDetail(executionNotice)).toBe(true);
  expect(turnItemOutputText(executionNotice)).toContain("Incomplete model execution telemetry");
});

import type { AssetResource, OrchestrationV2TurnItem } from "@t3tools/contracts";
import { toolOutputImageBlocks, toolOutputImages } from "@t3tools/shared/toolOutput";
import * as DateTime from "effect/DateTime";
import { modelExecutionDetail } from "./modelExecution.ts";

const MAX_TEXT_BLOCK_DEPTH = 4;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isSummarizedValue(value: unknown): boolean {
  return isRecord(value) && value.truncated === true && typeof value.summary === "string";
}

function textFromBlocks(
  value: unknown,
  depth: number,
  imageBlocks: ReadonlyArray<unknown>,
): string | null {
  if (depth > MAX_TEXT_BLOCK_DEPTH) return null;
  if (typeof value === "string") return value;
  if (Array.isArray(value)) {
    const parts = value.map((block) => textFromBlocks(block, depth + 1, imageBlocks));
    return parts.every((part) => part !== null)
      ? parts.filter((part) => part !== "").join("\n")
      : null;
  }
  if (!isRecord(value)) return null;
  if (value.type === "text" && typeof value.text === "string") return value.text;
  if (value.type === "image") return imageBlocks.includes(value) ? "" : "[image]";
  if (value.type === "resource_link" && typeof value.uri === "string") return value.uri;
  if (value.type === "resource" && isRecord(value.resource)) {
    const resource = value.resource;
    if (typeof resource.text === "string") return resource.text;
    if (typeof resource.uri === "string") return resource.uri;
  }
  const keys = Object.keys(value).filter((key) => key !== "isError" && key !== "is_error");
  if (keys.length === 1 && keys[0] === "content")
    return textFromBlocks(value.content, depth + 1, imageBlocks);
  if (keys.length === 2 && keys.includes("content") && keys.includes("structuredContent")) {
    const text = textFromBlocks(value.content, depth + 1, imageBlocks);
    return text?.trim() ? text : null;
  }
  return null;
}

function parseJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

function prettyJsonText(text: string): string {
  const trimmed = text.trim();
  if (!/^[[{]/.test(trimmed)) return text;
  const whole = parseJson(trimmed);
  if (whole !== undefined) return JSON.stringify(whole, null, 2);
  const lines = trimmed.split("\n").filter((line) => line.trim());
  const documents = lines.map((line) => parseJson(line.trim()));
  if (documents.some((document) => document === undefined)) return text;
  return documents.map((document) => JSON.stringify(document, null, 2)).join("\n\n");
}

function formatToolValue(value: unknown, hasImagePreview = false): string | null {
  if (value === undefined || value === null) return null;
  if (hasImagePreview && isRecord(value) && value.type === "image") return null;
  const text = textFromBlocks(value, 0, toolOutputImageBlocks(value));
  if (text !== null) return text.trim() ? prettyJsonText(text) : null;
  let json: string | undefined;
  try {
    json = JSON.stringify(value, null, 2);
  } catch {
    return String(value);
  }
  if (json === undefined || json === "{}" || json === "[]") return null;
  return json;
}

export function toolCallLines(input: {
  readonly command?: string | undefined;
  readonly args?: unknown;
}): {
  readonly command: string | null;
  readonly args: ReadonlyArray<readonly [string, string]> | null;
  readonly argsText: string | null;
} {
  if (input.command !== undefined) {
    const command = input.command.trim();
    return { command: command || null, args: null, argsText: null };
  }
  const args = input.args;
  if (isRecord(args) && !isSummarizedValue(args)) {
    const entries = Object.entries(args).flatMap(
      ([key, value]): Array<readonly [string, string]> => {
        if (value === undefined) return [];
        // An empty string or null can be the point of a call (a clear or reset), so show it.
        return [
          [
            key,
            typeof value === "string" && value !== ""
              ? value
              : (JSON.stringify(value) ?? String(value)),
          ],
        ];
      },
    );
    return { command: null, args: entries.length > 0 ? entries : null, argsText: null };
  }
  return { command: null, args: null, argsText: formatToolValue(args) };
}

function toolCallHasLines(lines: ReturnType<typeof toolCallLines>): boolean {
  return lines.command !== null || lines.args !== null || lines.argsText !== null;
}

const LIVE_TURN_ITEM_STATUSES: ReadonlySet<OrchestrationV2TurnItem["status"]> = new Set([
  "idle",
  "pending",
  "running",
  "waiting",
]);

/**
 * A running item keeps one key, so an open row fetches once while it streams and
 * again when it finishes, not on every update.
 */
export function turnItemDetailRevision(item: OrchestrationV2TurnItem): string {
  return LIVE_TURN_ITEM_STATUSES.has(item.status) ? "live" : DateTime.formatIso(item.updatedAt);
}

export function turnItemNeedsDetailFetch(item: OrchestrationV2TurnItem): boolean {
  switch (item.type) {
    case "command_execution":
      return item.outputOmitted === true;
    case "dynamic_tool":
      return item.outputOmitted === true || isSummarizedValue(item.input);
    default:
      return false;
  }
}

function commandOutputText(output: string): string {
  if (!output.trimStart().startsWith('{"stdout"')) return output;
  const parsed = parseJson(output.trim());
  if (
    !isRecord(parsed) ||
    typeof parsed.stdout !== "string" ||
    typeof parsed.stderr !== "string" ||
    typeof parsed.interrupted !== "boolean"
  ) {
    return output;
  }
  return [parsed.stdout, parsed.stderr]
    .filter((part): part is string => typeof part === "string" && part.trim().length > 0)
    .join("\n");
}

export function turnItemOutputText(item: OrchestrationV2TurnItem): string | null {
  switch (item.type) {
    case "system_notice":
      return item.modelExecution ? modelExecutionDetail(item.modelExecution, item.message) : null;
    case "command_execution":
      return item.output?.trim() ? commandOutputText(item.output) || null : null;
    case "dynamic_tool":
      return item.outputOmitted === true
        ? null
        : formatToolValue(item.output, item.viewedImagePath !== undefined);
    case "file_search":
      return item.results?.length
        ? item.results
            .map((result) =>
              [
                `${result.fileName}${result.line === undefined ? "" : `:${result.line}`}`,
                result.preview?.trim(),
              ]
                .filter(Boolean)
                .join("\n"),
            )
            .join("\n")
        : null;
    case "web_search":
      return item.results?.length
        ? item.results
            .map((result) =>
              [
                result.title?.trim() || result.url,
                result.title ? result.url : undefined,
                result.snippet?.trim(),
              ]
                .filter(Boolean)
                .join("\n"),
            )
            .join("\n\n")
        : null;
    default:
      return null;
  }
}

export function turnItemOutputImages(
  item: OrchestrationV2TurnItem,
): ReadonlyArray<Extract<AssetResource, { readonly _tag: "tool-output-image" }>> {
  if (item.type !== "dynamic_tool" || item.outputOmitted === true) return [];
  return toolOutputImages(item.output).map((_, index) => ({
    _tag: "tool-output-image",
    threadId: item.threadId,
    itemId: item.id,
    index,
  }));
}

export function turnItemHasDetail(item: OrchestrationV2TurnItem): boolean {
  switch (item.type) {
    case "reasoning":
      return item.text.trim().length > 0;
    case "command_execution":
      return (
        toolCallLines({ command: item.input }).command !== null ||
        item.outputOmitted === true ||
        Boolean(item.output?.trim()) ||
        (item.exitCode !== undefined && item.exitCode !== 0)
      );
    case "file_change":
    case "checkpoint":
    case "fork":
    case "handoff":
      return true;
    case "file_search":
      return (item.results?.length ?? 0) > 0 || Boolean(item.pattern?.trim());
    case "web_search":
      return (item.results?.length ?? 0) > 0 || (item.patterns?.length ?? 0) > 0;
    case "dynamic_tool":
      return item.outputOmitted === true || toolCallHasLines(toolCallLines({ args: item.input }));
    case "approval_request":
      return Boolean(item.prompt?.trim());
    case "user_input_request":
      return item.questions.length > 0;
    case "notification":
      return Boolean(item.detail?.trim());
    case "system_notice":
      return item.modelExecution !== undefined || item.message.trim().length > 0;
    case "error":
      return item.failure.message.trim().length > 0;
    case "proposed_plan":
      return item.markdown.trim().length > 0;
    case "todo_list":
      return item.steps.length > 0;
    case "subagent":
      return item.childThreadId !== null;
    default:
      return false;
  }
}

import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import { describe, expect, it } from "vite-plus/test";
import { modelExecutionDetail, modelExecutionSummary } from "./modelExecution.ts";

const phase: OrchestrationV2ModelExecution = {
  version: 1,
  kind: "phase",
  nativeSessionId: "session-1",
  eventId: "event-1",
  sourceTimestamp: "2026-11-02T10:00:05.000Z",
  receivedAt: "2026-11-02T10:00:08.000Z",
  status: "completed",
  model: "actual-model",
  startSource: "observed",
  startedAt: "2026-11-02T10:00:00.000Z",
  endedAt: "2026-11-02T10:00:05.000Z",
  durationMs: 4800,
  gaps: [],
};

describe("model execution presentation", () => {
  it("uses provider duration rather than receipt latency and distinguishes timing evidence", () => {
    expect(modelExecutionSummary(phase)).toContain("actual-model · completed · 4.8s");
    const detail = modelExecutionDetail(phase);
    expect(detail).toContain("Provider elapsed: 4.8s");
    expect(detail).toContain(`Started (observed): ${phase.startedAt}`);
    expect(detail).toContain(`Provider event time: ${phase.sourceTimestamp}`);
    expect(detail).toContain(`Received: ${phase.receivedAt}`);
    expect(modelExecutionDetail({ ...phase, startSource: "estimated" })).toContain(
      `Started (estimated): ${phase.startedAt}`,
    );
    const { durationMs: _duration, ...withoutDuration } = phase;
    expect(modelExecutionSummary(withoutDuration)).not.toContain("5.0s");
    expect(modelExecutionDetail(withoutDuration)).toContain("Provider elapsed: not reported");
    expect(
      modelExecutionDetail({ ...phase, startSource: "unknown", startedAt: undefined }),
    ).toContain("Start: unknown");
  });

  it("keeps requested routing separate from effective, pending, and actual execution", () => {
    const route = {
      ...phase,
      kind: "route" as const,
      requestedModel: "Fusion",
      requestedPreference: "premium",
      effectivePreference: "standard",
      pendingPreference: "premium",
      activatingPreference: null,
    };
    expect(modelExecutionSummary(route)).not.toContain("actual-model");
    const detail = modelExecutionDetail(route);
    expect(detail).toContain("Routing state (not proof of model execution)");
    expect(detail).toContain("Requested model: Fusion");
    expect(detail).toContain("Requested routing: premium");
    expect(detail).toContain("Effective routing: standard");
    expect(detail).toContain("Pending routing: premium");
    expect(detail).toContain("Activating routing: none");
    expect(modelExecutionDetail({ ...route, pendingPreference: undefined })).not.toContain(
      "Pending routing:",
    );
  });

  it("surfaces fallback, failure, final provenance and incomplete telemetry without inventing success", () => {
    const failed = {
      ...phase,
      status: "failed",
      fallbackModel: "fallback-model",
      finalSourceModel: "final-model",
      finalSourcePhaseId: "final-phase",
      reason: "Provider unavailable",
      awaitingBackgroundWork: true,
      gaps: ["missing phase start", "duration incomplete"],
    };
    expect(modelExecutionSummary(failed)).toContain("failed");
    expect(modelExecutionSummary(failed)).toContain("final final-model");
    expect(modelExecutionSummary(failed)).toContain("telemetry gaps");
    const detail = modelExecutionDetail(failed);
    expect(detail).toContain("Fallback model: fallback-model");
    expect(detail).toContain("Final source model: final-model");
    expect(detail).toContain("Final source phase: final-phase");
    expect(detail).toContain("Reason: Provider unavailable");
    expect(detail).toContain("Background work: awaiting completion");
    expect(detail).toContain("Telemetry gaps:\n- missing phase start\n- duration incomplete");
  });
});

import type { OrchestrationV2ModelExecution } from "@t3tools/contracts";
import { formatDuration } from "@t3tools/shared/orchestrationTiming";

export function modelExecutionSummary(execution: OrchestrationV2ModelExecution): string {
  const subject =
    execution.kind === "phase"
      ? ["Model phase", execution.model ?? "model unknown", execution.role]
      : execution.kind === "gap"
        ? ["Model telemetry gap", execution.model]
        : [
            execution.kind === "selection" ? "Model selection (requested)" : "Model routing",
            execution.requestedModel,
            execution.effectivePreference
              ? `effective ${execution.effectivePreference}`
              : execution.requestedPreference
                ? `requested ${execution.requestedPreference}`
                : undefined,
          ];
  return [
    ...subject,
    execution.status,
    execution.kind === "phase" && execution.durationMs !== undefined
      ? formatDuration(execution.durationMs)
      : undefined,
    execution.finalSourceModel ? `final ${execution.finalSourceModel}` : undefined,
    execution.fallbackModel ? `fallback ${execution.fallbackModel}` : undefined,
    execution.gaps.length > 0 ? "telemetry gaps" : undefined,
  ]
    .filter(Boolean)
    .join(" · ");
}

export function modelExecutionDetail(
  execution: OrchestrationV2ModelExecution,
  message?: string,
): string {
  const lines: string[] = message?.trim() ? [message.trim(), ""] : [];
  const add = (label: string, value: string | number | null | undefined) => {
    if (value !== undefined) lines.push(`${label}: ${value === null ? "none" : value}`);
  };
  lines.push(
    execution.kind === "selection" || execution.kind === "route"
      ? "Routing state (not proof of model execution)"
      : execution.kind === "gap"
        ? "Incomplete model execution telemetry"
        : "Provider-reported model phase",
  );
  add("Status", execution.status);
  add("Model", execution.model);
  add("Role", execution.role);
  add("Phase kind", execution.phaseKind);
  add("Conversation scope", execution.conversationScope);
  add("Pattern", execution.pattern);
  if (execution.plannedModels?.length)
    lines.push(
      `Planned models (not execution evidence):\n${execution.plannedModels
        .map(
          (phase) => `- ${phase.role}: ${phase.model}${phase.phaseId ? ` (${phase.phaseId})` : ""}`,
        )
        .join("\n")}`,
    );
  add("Requested model", execution.requestedModel);
  add("Resolved virtual model", execution.syntheticModel);
  add("Requested routing", execution.requestedPreference);
  add("Effective routing", execution.effectivePreference);
  add("Pending routing", execution.pendingPreference);
  add("Activating routing", execution.activatingPreference);
  add(
    execution.startedAt ? `Started (${execution.startSource})` : "Start",
    execution.startedAt ?? execution.startSource,
  );
  add("Ended", execution.endedAt);
  add(
    "Provider elapsed",
    execution.durationMs === undefined ? "not reported" : formatDuration(execution.durationMs),
  );
  add(
    execution.kind === "selection"
      ? "Snapshot time"
      : execution.kind === "gap"
        ? "Gap detected"
        : "Provider event time",
    execution.sourceTimestamp,
  );
  add("Received", execution.receivedAt);
  add("Fallback model", execution.fallbackModel);
  add("Degraded to phase", execution.degradedToPhaseId);
  add("Final source model", execution.finalSourceModel);
  add("Final source phase", execution.finalSourcePhaseId);
  add("Reason", execution.reason);
  if (execution.awaitingBackgroundWork !== undefined) {
    add(
      "Background work",
      execution.awaitingBackgroundWork ? "awaiting completion" : "not pending",
    );
  }
  if (execution.endedWithBackgroundWork !== undefined)
    add("Phase ended with background work", execution.endedWithBackgroundWork ? "yes" : "no");
  add("Session", execution.nativeSessionId);
  add("Turn", execution.nativeTurnId);
  add("Fusion", execution.fusionId);
  add("Phase", execution.phaseId);
  add("Event", execution.eventId);
  add("Contract version", execution.contractVersion);
  if (execution.gaps.length > 0)
    lines.push(`Telemetry gaps:\n${execution.gaps.map((gap) => `- ${gap}`).join("\n")}`);
  return lines.join("\n");
}

import * as Effect from "effect/Effect";
