describe("orchestration V2 contracts", () => {
  it("round-trips optional model execution metadata through runtime and JSON notices without breaking old histories", () => {
    const notice = {
      id: "model-notice",
      type: "system_notice",
      threadId: "thread-1",
      runId: null,
      nodeId: null,
      providerThreadId: null,
      providerTurnId: null,
      nativeItemRef: null,
      parentItemId: null,
      ordinal: 1,
      status: "completed",
      title: "Model execution",
