      ]),
    ).toEqual([{ id: "routing", value: "premium" }]);
    expect(
      providerOptionChoicesInCycleOrder(
        {
          ...descriptor,
          options: descriptor.options.slice(0, 1),
        },
        "premium",
        1,
      ),
    ).toEqual([]);
